/* Dhaka Crazy Taxi - 3D High-Fidelity Totoro Driver Model
 * Posed and exported via Blender MCP for cockpit driving placement
 */
(function() {
  'use strict';
  const CT = (window.CT = window.CT || {});
  function b64ToF32(b64) {
    const bin = atob(b64), len = bin.length, bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new Float32Array(bytes.buffer);
  }
  CT.TotoroModelData = {
    count: 16386,
    getPositions() { return b64ToF32(""); },
    getNormals() { return b64ToF32(""); },
    getColors() { return b64ToF32(""); }
  };
})();
